import { BodyShort, Box, Heading, HStack, InlineMessage, VStack } from '@navikt/ds-react';
import type { ComponentProps, PropsWithChildren, ReactElement } from 'react';
import type { Adresse, SistEndret } from 'src/lib/types/modiapersonoversikt-api';
import { formaterDato } from 'src/utils/string-utils';
import { twMerge } from 'tailwind-merge';

export const Group = ({
    title,
    icon,
    children
}: PropsWithChildren<{
    title?: string;
    icon?: ReactElement;
}>) => {
    return (
        <section className="mx-4 mb-2">
            <HStack className="relative" align="center">
                <div aria-hidden className="absolute -left-7 text-2xl text-ax-text-neutral-subtle">
                    {icon}
                </div>
                {title && (
                    <Heading as="h3" size="small">
                        {title}
                    </Heading>
                )}
            </HStack>
            <Box>{children}</Box>
        </section>
    );
};

export const InfoElement = ({
    children,
    title,
    icon
}: PropsWithChildren<{
    title?: string;
    icon?: ReactElement;
}>) => (
    <Box className="mb-6 mt-2">
        <HStack align="center" className="relative">
            {title && (
                <HStack>
                    {icon}
                    <Heading as="h4" size="xsmall" className={twMerge('text-ax-medium', icon && 'pl-1')}>
                        {title}
                    </Heading>
                </HStack>
            )}
        </HStack>
        <Box>{children}</Box>
    </Box>
);

export const Adresseinfo = ({
    adresse,
    size = 'small'
}: {
    adresse: Adresse;
    size?: ComponentProps<typeof BodyShort>['size'];
}) => {
    const coAdresse = adresse.coAdresse ? <BodyShort size={size}>{adresse.coAdresse}</BodyShort> : null;
    const adresselinje2 = adresse.linje2 ? <BodyShort size={size}>{adresse.linje2}</BodyShort> : null;
    const adresselinje3 = adresse.linje3 ? <BodyShort size={size}>{adresse.linje3}</BodyShort> : null;

    return (
        <>
            {coAdresse}
            <BodyShort size={size}>{adresse.linje1}</BodyShort>
            {adresselinje2}
            {adresselinje3}
        </>
    );
};

export const LastChanged = ({ sistEndret }: { sistEndret?: SistEndret | null }) => {
    if (!sistEndret) return null;

    const formatertDato = formaterDato(new Date(sistEndret.tidspunkt));
    const endretAvSystemKilde = sistEndret.system;
    const kilde = sistEndret.kilde.length > 0 ? `(kilde: ${sistEndret.kilde})` : null;

    return (
        <BodyShort textColor="subtle" className="text-sm">
            Endret {formatertDato} {endretAvSystemKilde && `av ${endretAvSystemKilde} ${kilde}`}
        </BodyShort>
    );
};

export const IngenInfo = ({ tekst }: { tekst: string }) => (
    <BodyShort size="small" textColor="subtle">
        {tekst}
    </BodyShort>
);

export const SeksjonFeil = ({ feilmeldinger }: { feilmeldinger: (string | undefined)[] }) => (
    <VStack gap="space-4">
        {feilmeldinger.filter(Boolean).map((feilmelding) => (
            <InlineMessage key={feilmelding} status="warning" size="small">
                {feilmelding}
            </InlineMessage>
        ))}
    </VStack>
);
